// Config: HubSpot user property names.
const CONFIG = {
  idProp: 'e_user_id',
  branchProp: 'e_user_default_branch',
  territoriesProp: 'e_user_all_territories',
  defaultTerritoryProp: 'e_user_default_territory',
  regionProp: 'branch_region',
};
const q = $input.first().json.query || {};
const eUserId = String(q.e_user_id || '').trim().toUpperCase();
const userProps = [
  CONFIG.idProp, CONFIG.branchProp, CONFIG.territoriesProp, CONFIG.defaultTerritoryProp, CONFIG.regionProp,
  'hs_given_name', 'hs_family_name', 'hs_email', 'hs_searchable_calculated_name',
];
if (!eUserId) {
  return [{ json: { ok: false, statusCode: 400, body: { error: 'Missing e_user_id' } } }];
}
return [{ json: { ok: true, eUserId, userProps, ...CONFIG } }];

const cfg = $('Validate').first().json;
const r = $input.first().json;
if (r.error) {
  return [{ json: { statusCode: 502, body: { error: 'HubSpot user lookup failed: ' + r.error, step: 'hubspot' } } }];
}
const results = Array.isArray(r.results) ? r.results : (r.id ? [r] : []);
if (!results.length) {
  return [{ json: { statusCode: 404, body: { error: 'No HubSpot user found with e_user_id ' + cfg.eUserId } } }];
}
const u = results[0];
const p = u.properties || {};
const territories = String(p[cfg.territoriesProp] || '').split(';')
  .map(s => s.trim()).filter((s, i, a) => s && a.indexOf(s) === i);
const name = [p.hs_given_name, p.hs_family_name].filter(Boolean).join(' ') || p.hs_searchable_calculated_name || '';
return [{ json: { statusCode: 200, body: {
  e_user_id: String(p[cfg.idProp] || cfg.eUserId).toUpperCase(),
  name,
  email: p.hs_email || '',
  default_branch: p[cfg.branchProp] || '',
  territories,
  default_territory: String(p[cfg.defaultTerritoryProp] || '').trim(),
  branch_region: String(p[cfg.regionProp] || '').trim(),
  hs_user_id: u.id || '',
  hs_owner_id: (u.owner && u.owner.id) || '',
} } }];
